int snd_timer_start(struct snd_timer *t) {
    // Cancel any existing timer
    timer_delete(t->timer_id);

    // Set the timer duration based on ticks and resolution
    struct itimerspec its;
    its.it_value.tv_sec = t->ticks / t->resolution;
    its.it_value.tv_nsec = (t->ticks % t->resolution) * 1e9 / t->resolution;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 0;

    // Create and start the timer
    timer_settime(t->timer_id, 0, &its, NULL);

    // Mark the timer as running
    t->running = 1;

    return 0;
}

int snd_timer_start(struct snd_timer *t) {
    // Cancel any existing timer
    if (t->running)
        alarm_cancel(&t->alarm);

    // Set the timer duration based on ticks and resolution
    t->alarm.it_value.tv_sec = t->ticks / t->resolution;
    t->alarm.it_value.tv_nsec = (t->ticks % t->resolution) * 1e9 / t->resolution;

    // Start the timer
    timer_settime(&t->alarm, 0, &t->alarm.it_value, NULL);
    t->running = 1;

    return 0;
}

int snd_timer_start(struct snd_timer *t) {
    if (t == NULL)
        return -1;

    // Cancel any existing timer
    t->cancel();

    // Set the timer duration based on ticks and resolution
    t->duration = t->ticks * t->resolution;

    // Mark the timer as running
    t->running = 1;

    return 0;
}

int snd_timer_start(struct snd_timer *t) {
    /* Cancel any existing timer */
    t->remaining = 0;

    /* Set the duration based on ticks and resolution */
    t->duration = t->ticks * t->resolution;

    /* Mark the timer as running */
    t->running = 1;

    return 0;
}

int snd_timer_start(struct snd_timer *t) {
    // Cancel any existing timer
    timer_cancel(&t->timer);

    // Set the timer duration based on ticks and resolution
    t->timer.expires = jiffies + (t->ticks * t->resolution);

    // Add the timer to the system timer list
    timer_add(&t->timer);

    // Mark the timer as running
    t->running = 1;

    return 0;
}
